.hju-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.hju-root,.hju-root *,.hju-root *::before,.hju-root *::after{box-sizing:border-box}
.hju-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.hju-root img{display:block;border:0;max-width:none}
.hju-root [hidden]{display:none!important}
.hju-root .n65_2966{word-break:break-word;background-color:color-mix(in srgb, var(--wa-surface, rgb(47 54 75)) 40%, transparent);align-content:stretch;display:flex;gap:14px;height:22px;align-items:center;justify-content:center;line-height:normal;font-style:normal;position:relative;flex-shrink:0;width:134px;white-space:nowrap;border-style:solid;border-color:var(--wa-line, #565e71);border-width:1px}
.hju-root .n65_2967{text-box-edge:cap alphabetic;text-box-trim:trim-both;font-family:"Tomorrow","Pretendard",system-ui,sans-serif;font-weight:400;position:relative;flex-shrink:0;color:var(--wa-point, #46cbff);font-size:16px;width:19px;height:12px}
.hju-root .n65_2968{text-box-edge:cap alphabetic;text-box-trim:trim-both;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;position:relative;flex-shrink:0;color:var(--wa-text-sub, #666669);font-size:12px;width:5px;height:8px}
.hju-root .n65_2969{text-box-edge:cap alphabetic;text-box-trim:trim-both;font-family:"Tomorrow","Pretendard",system-ui,sans-serif;font-weight:400;position:relative;flex-shrink:0;color:var(--wa-text-sub, #ccc);font-size:16px;width:28px;height:12px}
.hju-root[data-theme="light"]{background:var(--wa-bg, #e9edf5);color:var(--wa-text, #141a28)}
.hju-root[data-theme="light"] .n65_2966{background-color:color-mix(in srgb, var(--wa-point, rgb(226 231 241)) 55%, transparent);border-color:var(--wa-line, #c4ccdc)}
.hju-root[data-theme="light"] .n65_2967{color:var(--wa-point, #00658f)}
.hju-root[data-theme="light"] .n65_2968{color:var(--wa-text-sub, #6d7684)}
.hju-root[data-theme="light"] .n65_2969{color:var(--wa-text-sub, #3f4859)}
